//
// It must be the token of the person RUNNING the check. ERP logs every read under the token's
// identity, so a borrowed token attributes findings to someone who did not produce them - and
// where that person also reviews the cases, makes the reviewer the actor in their own evidence.
//
// TOKENS LAST 24 HOURS, so a workflow variable cannot sustain a monthly schedule. The production
// answer is a stored ERP credential holding a production token, created at deployment.
const ERP_BEARER = ($vars && $vars.ERP_BEARER) ? $vars.ERP_BEARER : '';

// WINDOWS RUN END TO END, all 2026-08-19:
//   2026-05-01..05 (5d)   137/137,  1 page,   93 applicants,  4 findings, AED 11,517
//   2026-06-01..30 (30d) 1197/1197, 6 pages, 605 applicants,  7 findings, AED 22,611.54
// The 137 is the spec's checksum and matched the last production run exactly. The June run is the
// first month-scale run ever to complete; 25 sequential chunks, zero ERP failures.
//
// THE WINDOW FOLLOWS THE CALENDAR (2026-08-30). It used to be two hand-edited constants pinned to
// June 2026, which a monthly schedule cannot use - an unattended run would have re-audited June
// forever. A run on the 15th audits the PREVIOUS FULL CALENDAR MONTH; the two-week lag lets
// payments settle. Set the OVERRIDE constants to pin a window for a deliberate one-off re-run.
const OVERRIDE_FROM = null;   // e.g. '2026-06-01'
const OVERRIDE_TO   = null;   // e.g. '2026-06-30'
function previousFullMonth() {
  const n = new Date();
  const first = new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth() - 1, 1));
  const y = first.getUTCFullYear();
  const m = first.getUTCMonth() + 1;
  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const p = function (x) { return String(x).padStart(2, '0'); };
  return { from: y + '-' + p(m) + '-01', to: y + '-' + p(m) + '-' + p(last) };
}
const _win = previousFullMonth();
const FROM = OVERRIDE_FROM || _win.from;
const TO   = OVERRIDE_TO   || _win.to;

if (!ERP_BEARER) {
  throw new Error('No ERP token. Set the n8n workflow variable ERP_BEARER ' +
    '(Settings -> Variables) to "Bearer <token>", belonging to the person running the check. It is ' +
    'deliberately not stored in this node - a token pasted into a Code node persists in the ' +
    'workflow JSON and in every version snapshot.');
}

return [{ json: {
