    // and this node's contract is that the entry path runs for real rather than being bypassed.
    callback_url: 'https://nnbyjbdbigcpoqtsczlz.supabase.co/functions/v1/ta-callback/' +
      'a1b2c3d4a1b2c3d4a1b2c3d4a1b2c3d4a1b2c3d4a1b2c3d4a1b2c3d4a1b2c3d4',
    audit_window: { kind: 'date_range', from: FROM, to: TO },
