}}];

// One row per portal case for the result workbook, PLUS a row for every charge that could not
// become a case at all.
//
// OUTPUT HYGIENE - the whole reason this node exists rather than dumping the payload: the check is
// marked 'Handles sensitive data = YES' and a Google Sheet is a far more shareable surface than
// the portal case store. So a row carries IDENTIFIERS AND AMOUNTS, which a reviewer needs, and
// deliberately NOT:
//   * applicant names            (in the transaction description, never projected)
//   * passport numbers           (likewise)
//   * card-holder / staff names  (the `card` field on the transaction - dropped here)
// The spec's own 'Where do the results go?' has Workbook UNTICKED, so the sheet itself is a
// declared deviation, not something the spec asked for.
const payload = $input.first().json || {};
const summary = (payload.result_data && payload.result_data.summary) || {};
const cases = (payload.result_data && payload.result_data.cases) || [];

let scored = {};
try { scored = $('Score Cases').first().json || {}; } catch (e) {}

const runMeta = {
  run_id: payload.run_id,
  run_date: summary.run_date || '',
  window: (summary.range_start || '') + '..' + (summary.range_end || '')
};

function ticketSummary(tickets) {
  return (tickets || []).map(function (t) {
    const amt = (t.amount_aed === null || t.amount_aed === undefined) ? 'no-amount' : t.amount_aed;
    return t.id + ':' + (t.status || '?') + '/' + (t.outcome || '-') + '/' + amt + '/g' + t.gate;
  }).join(' | ');
}

const rows = cases.map(function (c) {
  const m = c.metadata || {};
  return { json: Object.assign({}, runMeta, {
    applicant_id: m.applicant_id,
    portal_state: c.new_state,
    previous_state: c.previous_state || '',
    reason_code: c.reason_code,
    reason_text: c.reason_text,
    money_verdict: m.money_verdict || '',
    money_state: m.money_state || '',
    gate_reason: m.gate_reason || '',
    repeat_review: m.repeat_review ? 'yes' : 'no',
    dummy_ticket_count: m.dummy_ticket_count,
    exposure_aed: m.exposure_aed,
    driving_ticket_id: m.driving_ticket_id || '',
    flags: (m.flags || []).join(', '),
    tickets: ticketSummary(m.tickets),
    hustler_url: m.hustler_workflow_url || ''
  })};
});

