    reason_code: 'applicant_id_unresolved',
    reason_text: 'Dummy-ticket charge with no applicant id in its description and none on the ' +
      'transaction detail. Cannot be keyed to a case; needs manual attribution.',
    money_verdict: '', money_state: 'pending', gate_reason: 'gate_20_identity_unresolved',
    repeat_review: 'no', dummy_ticket_count: '', exposure_aed: '',
    driving_ticket_id: '', flags: 'unattributable',
    tickets: 'transaction ' + t.id + ' dated ' + (t.date || '?'),
    hustler_url: ''
  })});
}
for (const t of (scored.housemaid_charges || [])) {
  rows.push({ json: Object.assign({}, runMeta, {
    applicant_id: '', portal_state: 'out_of_scope_housemaid',
    reason_code: 'housemaid_charge',
    reason_text: 'Charge in the dummy-ticket expense that resolves a HOUSEMAID, not an applicant. ' +
      'Out of scope for this check by owner ruling; listed so it is visible rather than dropped.',
    money_verdict: '', money_state: 'pending', gate_reason: 'applicants_only_by_ruling',
    repeat_review: 'no', dummy_ticket_count: '', exposure_aed: '',
    driving_ticket_id: '', flags: 'out_of_scope',
    tickets: 'transaction ' + t.id + ' dated ' + (t.date || '?'),
    hustler_url: ''
  })});
}

if (!rows.length) return [];
return rows;

// The residue only. Everything settleable from structured fields was settled by a gate; this picks
// out the two shapes that genuinely need a person's words read.
//
// Runs AFTER the results callback and after the workbook writes by design: the reds are already
// visible as provisional, so a slow or failing model cannot delay or cost them.
//
//   RULE 1 (Order 120) - a dummy ticket with outcome 'Used'. Did the record explain the travel?
//   RULE 2 (Order 130) - a finding. Does the record claim the refund happened outside ERP?
//
// THE WRITTEN RECORD IS RE-READ FROM THE 0-FETCH OUTPUT, NOT FROM THE SCORED TICKET.
// scoreTicket rebuilds each ticket from a base object carrying only the seven scoring fields, so
// the notes do not survive it. Reading them from the scored ticket produced an empty record on
// EVERY case and the model answered NO_TEXT to a question it had been starved of - including a
// ticket whose note ran to 152 characters. Sourcing them here also keeps staff-written text out
// of the portal payload and out of the workbook, which is where it belongs.
const scored = $('Score Cases').first().json || {};
const validated = scored.validated || $('Validate Inputs').first().json;
const cases = scored.cases || [];

// applicant_id -> ticket_id -> the projected ticket, notes included
const notesByApplicant = {};
try {
  for (const it of $('Fetch Tickets (0-Fetch)').all()) {
    const f = it.json || {};
    if (f.applicant_id === undefined) continue;
    const byTicket = {};
    for (const t of (f.tickets || [])) byTicket[String(t.id)] = t;
    notesByApplicant[String(f.applicant_id)] = byTicket;
  }
} catch (e) {
  throw new Error('Verifier: could not read the enrichment output to recover the written record (' +
    e.message + '). Refusing to ask the model to judge an empty record - it would answer NO_TEXT ' +
    'and that would look like an honest absence.');
}

function withRecord(applicantId, t) {
  const src = (notesByApplicant[String(applicantId)] || {})[String(t.id)] || {};
  const notes = src.notes || {};
  return Object.assign({}, t, {
    notes: notes,
    has_written_record: Object.keys(notes).length > 0,
    from_code: src.from_code || '', to_code: src.to_code || '',
    refund_in: src.refund_in || ''
  });
}

const out = [];
let withText = 0, withoutText = 0, notFoundInEnrichment = 0;

for (const c of cases) {
  if (c.infrastructure) continue;                 // an outage has no written record to read
  const used = (c.tickets || []).filter(function (t) { return t.verdict === 'used_review'; })
    .map(function (t) { return withRecord(c.applicant_id, t); });
  const findings = (c.tickets || []).filter(function (t) {
    return t.verdict === 'financial_loss' || t.verdict === 'refund_overdue';
  }).map(function (t) { return withRecord(c.applicant_id, t); });

  if (!used.length && !findings.length) continue;

  for (const t of used.concat(findings)) {
    const known = (notesByApplicant[String(c.applicant_id)] || {})[String(t.id)];
    if (!known) notFoundInEnrichment++;
    else if (t.has_written_record) withText++; else withoutText++;
  }

  out.push({ json: {
    case_key: c.case_key,
    applicant_id: c.applicant_id,
    money_verdict: c.verdict,
    money_state: c.state,
    rule_1_tickets: used,
    rule_2_tickets: findings,
    erp_token: validated.erp_token,
    erp_device_id: validated.erp_device_id,
    erp_is_auth: validated.erp_is_auth
  }});
}

// A ticket the enrichment step never returned cannot be judged on its record. Fail loud rather
// than let it read as a clean absence.
if (notFoundInEnrichment > 0) {
  throw new Error('Verifier: ' + notFoundInEnrichment + ' ticket(s) selected for review were not ' +
    'found in the enrichment output, so their written record cannot be recovered. Refusing to ask ' +
    'the model to judge them - NO_TEXT would be indistinguishable from a real absence.');
}

// Surfaced so a future silent drop shows up as a number rather than as unanimous NO_TEXT.
if (out.length) {
  out[0].json.__record_stats = { tickets_with_written_record: withText,
    tickets_without_written_record: withoutText };
}
return out;

// Assemble exactly what each verifier rule is allowed to be decided on, and nothing else.
//
// The all-time ERP search uses operation 'like' deliberately: 'contains' returns HTTP 500 on this
// endpoint (a wrong operator, not a permission), which is why an earlier spec revision believed
// the call was blocked. AND an empty history only counts as evidence when the walk is PROVEN
// complete - pulled == totalElements - so that assertion travels with the bundle. A failed or
// truncated call is not an absence.
//
// PASSPORT NUMBERS ARE STRIPPED before anything reaches the model. They appear in transaction
// descriptions, the verifier has no use for them, and the check is marked 'Handles sensitive
// data = YES'.
const src = $('Select For Verifier').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json; });

if (res.length !== src.length) {
  throw new Error('Verifier: ' + src.length + ' cases but ' + res.length + ' all-time responses. ' +
    'Refusing to pair refund history to a case by index when the counts disagree.');
}

function redact(s) {
  return String(s || '')
    .replace(/Passport\s*Number\s*[-–:]\s*\S+/gi, 'Passport Number - [redacted]')
    .slice(0, 700);
}

const out = [];
for (let i = 0; i < src.length; i++) {
  const c = src[i];
  const r = res[i] || {};
  let body = r.body !== undefined ? r.body : r;
  if (Array.isArray(body)) body = body[0] || {};

  const status = r.statusCode;
  const declared = body && body.totalElements;
  const rows = Array.isArray(body && body.content) ? body.content : [];
  const complete = (status === 200) && (typeof declared === 'number') && (rows.length === declared);

  // Negative rows are reversals - a refund posted back against the same expense.
  const reversals = rows.filter(function (t) { return Number(t.amount) < 0; })
    .map(function (t) { return { id: t.id, date: t.date, amount: t.amount, description: redact(t.description) }; });

  const history = {
    call_ok: status === 200,
    operation_used: 'like',
    declared_total: declared,
    rows_pulled: rows.length,
    walk_complete: complete,
    absence_is_evidence: complete,
    reversal_rows: reversals,
    charge_rows: rows.length - reversals.length
  };

  function ticketEvidence(t) {
    return {
      ticket_id: t.id, status: t.status, outcome: t.outcome,
      amount_aed: t.amount_aed, currency: t.currency,
      scheduled_refund_on: t.refund_on || null,
      auto_refund_type: t.auto_type || null,
      refund_reason: t.refundReason || null,
      written_record: t.notes || {},
      has_written_record: !!(t.notes && Object.keys(t.notes).length)
    };
  }

  const r1 = (c.rule_1_tickets || []).map(ticketEvidence);
  const r2 = (c.rule_2_tickets || []).map(ticketEvidence);

  out.push({ json: {
    case_key: c.case_key, applicant_id: c.applicant_id,
    money_verdict: c.money_verdict, money_state: c.money_state,
    rule_1_tickets: r1, rule_2_tickets: r2,
    refund_history: history,
    any_written_record: r1.concat(r2).some(function (t) { return t.has_written_record; }),
    evidence_json: JSON.stringify({
      case_key: c.case_key,
      rule_1_used_tickets: r1,
      rule_2_finding_tickets: r2,
      all_time_refund_history: history
    })
  }});
}
return out;

