parameters.jsCode:
// WHERE THE MODEL'S ANSWER IS ACTUALLY ENFORCED.
//
// The prompt asks for discipline; this node imposes it. Only two model verdicts may move anything,
// and each needs its evidence present:
//   RULE 1: EXPLAINED + a non-empty quoted sentence        -> that TICKET becomes clean_explained
//   RULE 2: CLAIMED_OFF_ERP + a non-empty quoted sentence  -> that TICKET becomes 'unresolved'
//           (pending - evidence CLAIMED, not verified). IT NEVER CLEARS THE AMOUNT.
// Everything else - NOT_EXPLAINED, NO_CLAIM, NO_TEXT, UNRESOLVED, a missing verdict, a model
// error, an unparseable answer - leaves the ticket exactly as the deterministic gates left it.
// There is no path here by which a confirmed loss becomes clean.
//
// Each decision also records whether a written record EXISTED, independently of what the model
// made of it. Those two were conflated once already: the notes were being stripped upstream, the
// model answered NO_TEXT on every case, and unanimous NO_TEXT looked exactly like an honest
// absence. Never let them collapse into one signal again.
//
// The clean is TICKET-SCOPED and the case then re-takes the worst of its REMAINING tickets. That
// is the fix for the spec recheck's severity-1: one explained emergency must never absorb a
// sibling's overdue red.
const bundles = $('Build Evidence Bundle').all().map(function (i) { return i.json; });
const answers = $input.all().map(function (i) { return i.json; });
const scored = $('Score Cases').first().json || {};
const validated = scored.validated || $('Validate Inputs').first().json;

const SEVERITY = ['financial_loss', 'used_review', 'refund_overdue', 'awaiting_scheduled_refund',
  'unsettled', 'refunded', 'immaterial', 'clean_explained'];
const STATE = {
  financial_loss: 'finding', refund_overdue: 'finding',
  refunded: 'clean', clean_explained: 'clean',
  awaiting_scheduled_refund: 'pending', immaterial: 'pending', erp_unreachable: 'pending',
  unsettled: 'pending', unresolved: 'pending',
  used_review: 'verifier', repeat_bookings: 'verifier'
};

const caseByKey = {};
for (const c of (scored.cases || [])) caseByKey[String(c.case_key)] = c;

function answerFor(idx, caseKey) {
  // Prefer positional pairing, but verify the model echoed the same case. A mismatched echo is
  // treated as no answer at all rather than applied to the wrong person.
  const a = answers[idx];
  if (!a) return null;
  const payload = (a.output !== undefined && a.output !== null) ? a.output : a;
  if (payload && payload.case_key !== undefined && String(payload.case_key) !== String(caseKey)) return null;
  return payload;
}

const out = [];
let applied_rule1 = 0, applied_rule2 = 0, refused = 0, no_answer = 0, auditor_review = 0;
let judged_with_record = 0, judged_without_record = 0;

for (let i = 0; i < bundles.length; i++) {
  const b = bundles[i];
  const caseRow = caseByKey[String(b.case_key)];
  if (!caseRow) continue;

  // ticket_id -> did a written record exist at all
  const hadRecord = {};
  for (const t of (b.rule_1_tickets || []).concat(b.rule_2_tickets || [])) {
    hadRecord[String(t.ticket_id)] = !!t.has_written_record;
  }

  const ans = answerFor(i, b.case_key);
  const verdicts = (ans && Array.isArray(ans.verdicts)) ? ans.verdicts : [];
  const byTicket = {};
  for (const v of verdicts) if (v && v.ticket_id !== undefined) byTicket[String(v.ticket_id)] = v;
  if (!verdicts.length) no_answer++;

  const decisions = [];
  const patched = (caseRow.tickets || []).map(function (t) {
    const v = byTicket[String(t.id)];
    const model = v ? String(v.verdict || '').toUpperCase() : 'NO_ANSWER';
    const quote = v ? String(v.quoted_sentence || '').trim() : '';
    const had = hadRecord[String(t.id)];

    // RULE 1 - only an EXPLAINED with a quoted sentence may clear a Used ticket.
    if (t.verdict === 'used_review') {
      if (had === true) judged_with_record++; else if (had === false) judged_without_record++;
      if (model === 'EXPLAINED' && quote.length > 0) {
        applied_rule1++;
        decisions.push({ ticket_id: t.id, rule: 1, model_verdict: model, applied: 'clean_explained',
          had_written_record: had, quoted_sentence: quote.slice(0, 400) });
        return Object.assign({}, t, { verdict: 'clean_explained', reason: 'verifier_emergency_explained' });
      }
      if (model === 'EXPLAINED' && !quote) refused++;   // asserted but did not quote: not accepted
      if (model === 'NO_TEXT' || model === 'UNRESOLVED' || model === 'NO_ANSWER') auditor_review++;
      decisions.push({ ticket_id: t.id, rule: 1, model_verdict: model, applied: 'unchanged',
        had_written_record: had, quoted_sentence: quote.slice(0, 400) });
      return t;   // stays route-to-verifier for a human. Never green.
    }

    // RULE 2 - only a CLAIMED_OFF_ERP with a quoted sentence may downgrade a finding, and only to
    // PENDING. The amount is preserved on the case as a claim, never written off.
    if (STATE[t.verdict] === 'finding') {
      if (had === true) judged_with_record++; else if (had === false) judged_without_record++;
      if (model === 'CLAIMED_OFF_ERP' && quote.length > 0) {
        applied_rule2++;
        decisions.push({ ticket_id: t.id, rule: 2, model_verdict: model,
          applied: 'unresolved_evidence_claimed', had_written_record: had,
          quoted_sentence: quote.slice(0, 400),
          amount_named: !!(v && v.amount_named), route_named: !!(v && v.route_named),
          who_must_produce_receipt: v ? String(v.who_must_produce_receipt || '').slice(0, 120) : '' });
        return Object.assign({}, t, { verdict: 'unresolved',
          reason: 'evidence_claimed_not_verified',
          claimed_amount_aed: t.amount_aed });   // amount kept, never cleared
      }
      if (model === 'CLAIMED_OFF_ERP' && !quote) refused++;
      if (model === 'NO_TEXT' || model === 'UNRESOLVED' || model === 'NO_ANSWER') auditor_review++;
      decisions.push({ ticket_id: t.id, rule: 2, model_verdict: model, applied: 'unchanged',
        had_written_record: had, quoted_sentence: quote.slice(0, 400) });
      return t;   // the finding stands.
    }
    return t;
  });

  // Re-aggregate: the case takes the worst of what REMAINS.
  let worst = patched[0];
  for (const t of patched) {
    const a = SEVERITY.indexOf(t.verdict), c2 = SEVERITY.indexOf(worst.verdict);
    if (a !== -1 && (c2 === -1 || a < c2)) worst = t;
  }
  let exposure = 0, claimed = 0;
  for (const t of patched) {
    if (STATE[t.verdict] === 'finding' && t.amount_aed) exposure += t.amount_aed;
    if (t.verdict === 'unresolved' && t.claimed_amount_aed) claimed += t.claimed_amount_aed;
  }

  const finalState = STATE[worst.verdict] || 'pending';
  out.push({ json: {
    case_key: b.case_key, applicant_id: b.applicant_id,
    before: { verdict: caseRow.verdict, state: caseRow.state, exposure_aed: caseRow.exposure_aed },
    after: { verdict: worst.verdict, state: finalState,
      exposure_aed: Math.round(exposure * 100) / 100,
      exposure_claimed_not_verified_aed: Math.round(claimed * 100) / 100 },
    changed: caseRow.verdict !== worst.verdict,
    decisions: decisions,
    refund_history_complete: !!(b.refund_history && b.refund_history.walk_complete),
    any_written_record: !!b.any_written_record,
    run_id: validated.run_id, run_date: validated.run_date
  }});
}

// TRIPWIRE ON THE VERIFIER ITSELF. If the model returned NO_TEXT for every ticket while records
// demonstrably existed, the pipeline is starving it again - which is precisely the failure this
// node was rewritten to make visible. Report it loudly rather than banking unanimous NO_TEXT.
const counters = { applied_rule1: applied_rule1, applied_rule2: applied_rule2,
  refused_unquoted: refused, no_model_answer: no_answer, auditor_review: auditor_review,
  judged_with_written_record: judged_with_record,
  judged_without_written_record: judged_without_record,
  suspected_starved_verifier: (judged_with_record > 0 && applied_rule1 === 0 && applied_rule2 === 0
    && auditor_review === judged_with_record + judged_without_record) };
if (out.length) out[out.length - 1].json.__counters = counters;
return out;

// One row per verifier decision. Identifiers and amounts only - no names, no passport numbers, no
// card-holder names. The quoted sentence IS the evidence a reviewer needs, so it travels; it is
// capped and was passport-redacted upstream.
const rows = [];
for (const item of $input.all()) {
  const c = item.json || {};
  for (const d of (c.decisions || [])) {
    rows.push({ json: {
      run_id: c.run_id, run_date: c.run_date,
      applicant_id: c.applicant_id,
      ticket_id: d.ticket_id,
      rule: d.rule,
      model_verdict: d.model_verdict,
      applied: d.applied,
      // Whether a record EXISTED is reported separately from what the model made of it, so
      // 'the model saw nothing' can never again be mistaken for 'there was nothing to see'.
      ticket_had_written_record: d.had_written_record === undefined ? '' : d.had_written_record,
      quoted_sentence: d.quoted_sentence || '',
      amount_named: d.amount_named === undefined ? '' : d.amount_named,
      route_named: d.route_named === undefined ? '' : d.route_named,
      who_must_produce_receipt: d.who_must_produce_receipt || '',
      case_before: c.before ? (c.before.verdict + '/' + c.before.state) : '',
      case_after: c.after ? (c.after.verdict + '/' + c.after.state) : '',
      exposure_after_aed: c.after ? c.after.exposure_aed : '',
      exposure_claimed_not_verified_aed: c.after ? c.after.exposure_claimed_not_verified_aed : '',
      refund_history_complete: c.refund_history_complete,
      any_written_record: c.any_written_record
    }});
  }
}
return rows;

// Fail Loudly (Dummy Tickets Housemaids, 1-Score) - the end of the error rail.
//
// WHY THE RAIL EXISTS. This flow acquires the ERP lease before Get Dummy Ticket Transactions and
// releases it after the verdict rows reach the sheet - which is AFTER the last ERP call, because
// Get All-Time Refunds sits downstream of the case and summary writes. Until 2026-08-23 there
// was no lease at all; now that there is one, every way this flow can die between those two
// points - a breaker trip, a budget refusal, a dead token, a sub-workflow throw - would
// otherwise leave the lease held by a run that no longer exists, and the staleness backstop only
// clears it after 3 hours. That is a 3-hour hole in the queue after every failure.
//
// WHY IT IS AN ERROR OUTPUT AND NOT THE ERROR TRIGGER. On Workflow Crash fires in a SEPARATE
// execution, where $('Validate Inputs') does not resolve - so it cannot name the run that holds
// the lease, and a release that guesses is the silent-steal path the lease exists to prevent. An
// error OUTPUT stays inside the same execution, so the release names the real holder. The Error
// Trigger keeps its job of reporting a crash to the caller; it does not touch the lease.
//
// WHY IT RE-THROWS. n8n marks an execution SUCCESS when it runs off the end of an error output.
// A rail that released and stopped would turn a failed audit into one the run log reports as
// fine - strictly worse than the stranded lease it was added to fix, because a stranded lease is
// loud within three hours and a silently-successful audit is never looked at again.
// READ THE FAILURE FROM Capture Failure, NOT FROM $input. Release Lease (error) sits between the
// failing node and this one, and an Execute Sub-workflow node REPLACES the item with the lease's
// own return value - so $input here holds the lease's answer, not the error. Reading $input is
// what this rail did until 2026-08-23, and it would have reported "unknown node / unknown error"
// on every failure it ever handled. Nobody saw it because no rail in this project has yet fired.
let msg = 'unknown error', failedNode = 'unknown node';
try {
  const f = ($('Capture Failure').first().json || {})._failure || {};
  if (f.message) msg = String(f.message);
  if (f.node) failedNode = String(f.node);
} catch (e) { }

let runId = 'unknown';
let auditWindow = '';
try {
  const v = $('Validate Inputs').first().json;
  runId = String(v.run_id);
  auditWindow = String(v.range_start || '') + ' to ' + String(v.range_end || '');
} catch (e) { }

console.log(JSON.stringify({ stage: 'dummy_tickets_hm_1score_failed', run_id: runId,
  audit_window: auditWindow, failed_node: failedNode, error: msg,
  note: 'ERP lease RELEASED on the error rail. Without it this run would have held the lease ' +
        'until the 3-hour staleness backstop, because Release ERP Lease sits at the end of the ' +
        'delivery chain and never runs when the flow dies.' }));

throw new Error('DUMMY TICKETS HOUSEMAIDS 1-SCORE FAILED at "' + failedNode + '": ' + msg +
  ' | The ERP lease was released, so the next audit is not blocked. | Anything already written to ' +
  'the sheet for this run is a PARTIAL and must not be read as the month: the run died before ' +
  'its verdicts were delivered. Re-run the same window once the cause is fixed.');

// ERP PRE-FLIGHT BUDGET GATE — ERP-LOAD-POLICY.md §3. Canonical: tools/erp_preflight_gate.js.
//
// Sits between Select Unresolved and Resolve Applicants, which is the last point before the
// first PER-ENTITY ERP call (Fetch Tickets, launched from Resolve Applicants' chunks). Everything upstream of here is the paginated sweep, whose cost is a
// handful of pages; everything downstream multiplies by the population.
//
// WHY VOLUME NEEDS ITS OWN CONTROL. Pacing bounds requests per second. It does not bound how many
// there are. This flow paced perfectly at 4 req/s still makes 2N calls for a population of N, and
// that is the shape of the failure that took ERP down three times: a check tested on a week of
// transactions behaves identically on a year of them, and nothing in between makes the cost
// visible before the calls go out.
//
// IT HARD-FAILS. It does not trim the population to fit. Auto-capping produces a run that
// completes with incomplete coverage, and a partial audit that looks complete is the single
// failure this whole check family exists to avoid.

// --- per-flow constants: what this run actually costs, stated honestly -----------------------
// 1. Fetch Tickets (0-Fetch)  - one call per UNIQUE applicant. Worst case is one applicant per
//                               transaction, so it is budgeted at 1 per transaction rather than
//                               guessed lower - a budget that assumes the happy case is not a
//                               budget.
// 2. Get All-Time Refunds     - one call per case selected for the verifier, worst case one per
//                               transaction.
//
// WAS 3. The third was Get Transaction Detail, one call per in-window transaction, DELETED
// 2026-08-24: GET /accounting/transactions/{id} is not a mapped route, and the endpoint that is
// returns the same projection the sweep already holds (ENDPOINT-FINDING.md). A third of this
// check's modelled ERP load was being spent on a call that could never succeed.
const ERP_CALLS_PER_TRANSACTION = 2;
const SWEEP_CALLS_FALLBACK = 5;      // pages, when the run cannot report what it walked

const DEFAULT_BUDGET = 2000;         // ERP-LOAD-POLICY.md §1 — a run that names no budget
const SIGNOFF_THRESHOLD = 15000;     // above this a human decision must be recorded first

const _validated = $('Validate Inputs').first().json || {};
const params = _validated.params || {};

const askedBudget = Number(params.erp_call_budget);
const budget = Number.isFinite(askedBudget) && askedBudget > 0 ? askedBudget : DEFAULT_BUDGET;

// Prefer what the run MEASURED over the constant: the sweep already knows how many pages it
// walked, and a real number beats an estimate that quietly ages.
let measuredPages = 0;
try { measuredPages = $('Get Dummy Ticket Transactions').all().length; } catch (e) { measuredPages = 0; }
const sweepCalls = measuredPages > 0 ? measuredPages : SWEEP_CALLS_FALLBACK;

const rows = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && !r._empty && !r._seed_only && r.transaction_id !== undefined; });
